    ('e6fed564-7213-4395-9814-1c24d0c08287'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd3-2026-10-04-s020-rollback:e6fed564-7213-4395-9814-1c24d0c08287:period_name', 'rollback of fields-wd3-2026-10-04-s020: period_name None restored on Prassa', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4500) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (band, round 0, ancient_nerds_original.geojson:Period)", "decision": "replace", "status": "RULE", "reasoning": "no source and no type rule dates the site; the 2025 import put it in the period ''4500 - 3000 BC'', and the band rule writes that period''s beginning (-4500)", "value_page": null, "model": null}]'::jsonb),
